def get(st, a):
    res = 0
    for i in range(len(a)):
        if (st >> i) & 1 == 1:
            res += a[i]
    return res

def main():
    n, m = map(int, input().split())
    mm = 1 << n
    a = [list(map(int, input().split())) for _ in range(m)]

    dp = [[0] * mm for _ in range(m)]
    for i in range(mm):
        dp[0][i] = get(i, a[0])

    for i in range(1, m):
        for j in range(mm):
            for k in range(mm):
                if ((j | (j << 1) | (j >> 1)) & k) == 0:
                    dp[i][k] = max(dp[i][k], dp[i - 1][j] + get(k, a[i]))

    ans = max(dp[m - 1])
    print(ans)

if __name__ == "__main__":
    main()
