### Python

```python
import sys

def main():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    mm = 1 << n
    # 读取每天每个装置的数据量
    a = [[0] * n for _ in range(m)]
    for day in range(m):
        for i in range(n):
            a[day][i] = int(next(it))

    # 预处理每天每种状态的数据和
    val = [[0] * mm for _ in range(m)]
    for day in range(m):
        for mask in range(mm):
            s = 0
            for i in range(n):
                if (mask >> i) & 1:
                    s += a[day][i]
            val[day][mask] = s

    # dp[day][mask]
    dp = [[0] * mm for _ in range(m)]
    # 第一天
    for mask in range(mm):
        dp[0][mask] = val[0][mask]

    # 后续天数
    for day in range(1, m):
        for cur in range(mm):
            max_val = 0
            for prev in range(mm):
                # 前一天状态 prev，产生的影响范围
                ban = prev | (prev << 1) | (prev >> 1)
                ban &= (mm - 1)  # 只保留低 n 位，可省略
                if (cur & ban) == 0:
                    if dp[day - 1][prev] + val[day][cur] > max_val:
                        max_val = dp[day - 1][prev] + val[day][cur]
            dp[day][cur] = max_val

    ans = max(dp[m - 1])
    print(ans)

if __name__ == "__main__":
    main()
```

