        int n = sc.nextInt();
        int m = sc.nextInt();
        int mm = 1 << n;
        int[][] a = new int[m][n];
        for (int day = 0; day < m; day++) {
            for (int i = 0; i < n; i++) {
                a[day][i] = sc.nextInt();
